43	const PROCESSING_FEE = 5;
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	const BASE_PREMIUMS: Record<string, number> = {
46	  sword: 100,
47	  amulet: 60,
48	  staff: 80,
49	  potion: 40,
50	};
51	
52	const quote = (step: QuoteStep): StepResult => {
53	  const basePremium = step.items.reduce(
54	    (sum, item) => sum + BASE_PREMIUMS[item.type],
55	    0,
56	  );
57	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
58	  const premium = basePremium + firstInsuranceSurcharge + PROCESSING_FEE;
59	
60	  return { premium };
61	};
62	
63	export const runScenario = (scenario: Scenario): ScenarioResult => {
64	  return { results: scenario.steps.map((step) => quote(step as QuoteStep)) };
65	};
